// Экраны верификации без съёмки: new02 — отказ (причина из админки), new01 — верифицирована (B-12, значок «מאומת/ת»).
// Селфи не отправляется (кнопка «צילום» не нажимается). @data — только из-за одноразовых refresh-токенов.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { saveSession } from '../_shared/session';

const HINT = 'צריך לפחות תמונה אחת בפרופיל שרואים בה את הפנים שלך';
const CHIP = 'התמונה הראשית — הפנים שלך, בלי פילטרים';

// Причина отказа new02 — из карточки «האימות לא עבר» в профиле (её пишет админка, текст не зашиваем).
async function rejectReason(p: Page) {
  await p.goto('/profile');
  const title = p.getByText('האימות לא עבר', { exact: true });
  await expect(title).toBeVisible();
  const card = p.locator('div').filter({ has: title }).filter({ has: p.getByRole('button', { name: 'לנסות שוב' }) }).last();
  const lines = (await card.innerText()).split('\n').map((s) => s.trim()).filter(Boolean);
  const reason = lines[lines.indexOf('האימות לא עבר') + 1];
  expect(reason, 'причина отказа в карточке профиля').toBeTruthy();
  return reason!;
}

test.describe('Верификация лица — экраны (без съёмки)', () => {
  test.describe.configure({ timeout: 120_000 });

  test('Отказ: в профиле «האימות לא עבר» + причина + «לנסות שוב»; экран отказа 17.02b — причина, подсказка, чип, «לנסות שוב» 350/335, «להחלפת תמונות» @iphone @data (#4df1ca)', async ({ asUser }) => {
    const p = await asUser('new02');
    try {
      await p.setViewportSize({ width: 390, height: 844 });
      const reason = await rejectReason(p); // AC 6
      // Профиль → «לנסות שוב» → экран отказа с той же причиной (Р6, AC 6–7).
      await p.getByRole('button', { name: 'לנסות שוב' }).click();
      await p.waitForURL(/\/verif/);
      await expect(p.getByRole('alert')).toContainText(reason);
      await expect(p.getByText(HINT)).toBeVisible();
      await expect(p.getByText(CHIP)).toBeVisible();
      const retry = p.getByRole('button', { name: 'לנסות שוב' });
      const swap = p.getByRole('button', { name: 'להחלפת תמונות' });
      await expect(swap).toBeVisible();
      expect(Math.round((await retry.boundingBox())!.width), '«לנסות שוב» 350 на 390').toBe(350);
      // Чип и подсказка — над кнопкой, не под ней (Р2, Р6) — на 390.
      const chipBox = (await p.getByText(CHIP).boundingBox())!;
      expect(chipBox.y + chipBox.height, 'чип над «לנסות שוב»').toBeLessThanOrEqual((await retry.boundingBox())!.y);
      // Без строки про ручную проверку (Р8.1).
      await expect(p.getByText(/צוות Magnet בודק/)).toHaveCount(0);
      // 375: ширина кнопки 335 (Р6).
      await p.setViewportSize({ width: 375, height: 667 });
      await expect.poll(async () => Math.round((await retry.boundingBox())!.width), { message: '«לנסות שוב» 335 на 375' }).toBe(335);
    } finally {
      await saveSession(p, 'new02');
    }
  });

  test('Верифицирована: /verify — B-12 «את/ה מאומת/ת!», значок справа внизу аватара в белом круге; в профиле значок у имени @iphone @data (#4df1ca)', async ({ asUser }) => {
    const p = await asUser('new01');
    try {
      await p.setViewportSize({ width: 390, height: 844 });
      await p.goto('/verify');
      await expect(p.getByText('את/ה מאומת/ת!')).toBeVisible(); // AC 4
      await expect(p.getByText('התג כבר ליד השם שלך', { exact: false })).toBeVisible();
      await expect(p.getByRole('button', { name: 'המשך' })).toBeVisible();
      await expect(p.getByText(/צוות Magnet בודק/)).toHaveCount(0);
      // Значок (Р8.2, 865-905): центр значка правее и ниже центра самого большого аватара; фон круга — белый.
      const badge = p.getByRole('img', { name: 'מאומת/ת' });
      await expect(badge).toBeVisible();
      const geo = await badge.evaluate((b) => {
        const imgs = [...document.querySelectorAll('img, [role="img"]')].filter((e) => e !== b && !b.contains(e) && !e.contains(b));
        const r = b.getBoundingClientRect();
        const cx = r.x + r.width / 2, cy = r.y + r.height / 2;
        // аватар — крупное круглое фото (120–320px), ближайшее к значку
        const big = imgs.map((e) => e.getBoundingClientRect()).filter((q) => q.width >= 120 && q.width <= 320)
          .sort((x, y) => Math.hypot(x.x + x.width / 2 - cx, x.y + x.height / 2 - cy) - Math.hypot(y.x + y.width / 2 - cx, y.y + y.height / 2 - cy))[0];
        // белый круг — сам значок или ближайший предок с непрозрачным белым фоном
        let n: Element | null = b, bg = '';
        for (let i = 0; i < 4 && n; i++, n = n.parentElement) {
          const c = getComputedStyle(n).backgroundColor;
          if (/^rgba?\(255, 255, 255(, 1)?\)$/.test(c)) { bg = c; break; }
        }
        return { bx: r.x + r.width / 2, by: r.y + r.height / 2, ax: big.x + big.width / 2, ay: big.y + big.height / 2, bg };
      });
      expect(geo.bx, 'значок правее центра аватара').toBeGreaterThan(geo.ax);
      expect(geo.by, 'значок ниже центра аватара').toBeGreaterThan(geo.ay);
      expect(geo.bg, 'значок в белом круге').not.toBe('');
      // Профиль: значок «מאומת/ת» у имени (AC 5).
      await p.goto('/profile');
      await expect(p.getByRole('img', { name: 'מאומת/ת' }).first()).toBeVisible();
    } finally {
      await saveSession(p, 'new01');
    }
  });
});
